\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\begin{document}
\begin{tikzpicture}
\begin{axis}[
    title={Elliptic Paraboloid: $y = 4x^2 + 2z^2$},
    xlabel={$x$},
    ylabel={$z$},
    zlabel={$y$},
    view={60,30},
    domain=-1:1,
    y domain=-1:1,
    samples=30,
    colormap/viridis,
    colorbar,
    z buffer=sort,
    enlargelimits=false,
    ticks=none
]
% Plotting z = 4x^2 + 2y^2 and labeling axes x, z, y to represent y = 4x^2 + 2z^2
\addplot3[surf, shader=faceted interp] {4*x^2 + 2*y^2};
\end{axis}
\end{tikzpicture}
\end{document}

